using System; using System.Diagnostics; using System.IO; using System.Text; using System.Runtime.InteropServices; class L { [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern IntPtr FindWindow(string c,string n); [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern int GetWindowText(IntPtr h,StringBuilder s,int m); [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc e,IntPtr l); delegate bool EnumProc(IntPtr h,IntPtr l); static string Title(IntPtr h){var b=new StringBuilder(512); GetWindowText(h,b,512); return b.ToString();} static void Main(){ string root=AppDomain.CurrentDomain.BaseDirectory; string name=Environment.GetEnvironmentVariable("PKA_PLAYER_NAME"); if(string.IsNullOrWhiteSpace(name)){ EnumWindows((h,l)=>{ string t=Title(h); if(t.StartsWith("PokeAlliance - ")){ name=t.Substring(16); return false;} return true;}, IntPtr.Zero);} if(string.IsNullOrWhiteSpace(name)){ try{ string f=Path.Combine(root,"live-snapshot.json"); if(File.Exists(f)){ string s=File.ReadAllText(f); int i=s.IndexOf("\"name\""); if(i>0){ int a=s.IndexOf((char)34,i+6)+1; int b=s.IndexOf((char)34,a); if(b>a) name=s.Substring(a,b-a);}}}catch{} } if(!string.IsNullOrWhiteSpace(name)) Environment.SetEnvironmentVariable("PKA_PLAYER_NAME",name); var psi=new ProcessStartInfo(Path.Combine(root,"electron","PKA-Bot.exe")); psi.Arguments="\""+Path.Combine(root,"reconstruction","app")+"\""; psi.WorkingDirectory=root; psi.UseShellExecute=false; psi.EnvironmentVariables.Remove("ELECTRON_RUN_AS_NODE"); psi.EnvironmentVariables.Remove("ELECTRON_NO_ASAR"); Process.Start(psi); } }
